#include <iostream>
#include <vector>
#include <atcoder/modint>
using namespace std;
using namespace atcoder;
typedef modint998244353 mint;

int n, m, k;
vector<int> G[3005];
int c[3005];
mint dp[3005][3005][2][2];
mint dinv[3005];

int main(void)
{
  cin >> n >> m >> k;
  int u, v;
  for(int i = 1; i <= m; i++){
    cin >> u >> v;
    G[u].push_back(v), G[v].push_back(u);
  }
  for(int i = 1; i <= n; i++) cin >> c[i];
  for(int i = 1; i <= n; i++) dinv[i] = mint(G[i].size()).inv();

  dp[0][1][0][0] = 1;
  for(int i = 0; i < k; i++){
    for(int j = 1; j <= n; j++){
      for(int a = 0; a < 2; a++){
        for(int b = 0; b < 2; b++){

          for(auto u : G[j]){
            for(int na = a; na < 2; na++){
              for(int nb = b; nb < 2; nb++){
                if(c[u] == 1 && na+nb != a+b) continue;
                dp[i+1][u][na][nb] += dp[i][j][a][b] * dinv[j];
              }
            }
          }

        }
      }
    }
  }

  mint ans = 0;
  for(int i = 1; i <= k; i++) for(int j = 1; j <= n; j++) if(c[j]) ans += dp[i][j][1][1];
  cout << ans.val() << endl;

  return 0;
}
